public int frogJump(int n, int[] heights) {
    int[] energy = new int[n];
    energy[0] = 0;
    for (int i = 1; i < n; i++) {
        int jumpOne = energy[i - 1] + Math.abs(heights[i] - heights[i - 1]);
        int jumpTwo = i > 1
                ? energy[i - 2] + Math.abs(heights[i] - heights[i - 2])
                : Integer.MAX_VALUE;
        energy[i] = Math.min(jumpOne, jumpTwo);
    }
    return energy[n - 1];
}

