public class Solution {
    public int frogJump(int n, int[] heights) {
        return energy(n - 1, heights);
    }

    private int energy(int i, int[] heights) {
        if (i == 0) {
            return 0;
        }
        int jumpOne = energy(i - 1, heights) + Math.abs(heights[i] - heights[i - 1]);
        // Stair 1 has no two-step predecessor. The sentinel is never added to a cost.
        int jumpTwo = i > 1
                ? energy(i - 2, heights) + Math.abs(heights[i] - heights[i - 2])
                : Integer.MAX_VALUE;
        return Math.min(jumpOne, jumpTwo);
    }
}

memoization.code:
public class Solution {
    public int frogJump(int n, int[] heights) {
        // Null means unknown. Zero is a valid minimum energy and must be cached too.
        Integer[] memo = new Integer[n];
        return energy(n - 1, heights, memo);
    }

    private int energy(int i, int[] heights, Integer[] memo) {
        if (memo[i] != null) {
            return memo[i];
        }
        if (i == 0) {
            memo[i] = 0;
            return 0;
        }
        int jumpOne = energy(i - 1, heights, memo) + Math.abs(heights[i] - heights[i - 1]);
        int jumpTwo = i > 1
                ? energy(i - 2, heights, memo) + Math.abs(heights[i] - heights[i - 2])
                : Integer.MAX_VALUE;
        memo[i] = Math.min(jumpOne, jumpTwo);
        return memo[i];
    }
}

